import json

with open('/home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-10-projects-provenance-weight-training/dfca9e39-a910-4b0a-a3a3-662a0180b16f/tool-results/mcp-agent-ml-research-read_registry-1779292620354.txt') as f:
    outer = json.load(f)
inner = json.loads(outer['result'])
experiments = inner['data']['experiments']

# Comprehensive: find ALL unique eval-related field names across all experiments
print("=" * 80)
print("ALL UNIQUE EVAL/METRIC FIELD NAMES ACROSS ALL EXPERIMENTS")
print("=" * 80)

all_metric_fields = set()
all_top_eval_fields = set()

def collect_fields(obj, prefix=""):
    fields = set()
    if isinstance(obj, dict):
        for k, v in obj.items():
            full = f"{prefix}.{k}" if prefix else k
            fields.add(full)
            fields.update(collect_fields(v, full))
    return fields

for exp_id, exp in experiments.items():
    # metrics sub-dict
    if 'metrics' in exp and isinstance(exp['metrics'], dict):
        for k in exp['metrics']:
            all_metric_fields.add(k)
    # top-level eval fields
    for k in exp:
        if any(term in k.lower() for term in ['eval', 'ppl', 'downstream', 'accuracy']):
            all_top_eval_fields.add(k)

print("\nFields inside 'metrics' dict (union across all experiments):")
for f in sorted(all_metric_fields):
    print(f"  metrics.{f}")

print("\nTop-level eval-related fields:")
for f in sorted(all_top_eval_fields):
    print(f"  {f}")

# Count how many experiments have each metric field
print("\n\nFIELD FREQUENCY (how many experiments have each metric field):")
field_counts = {}
for exp_id, exp in experiments.items():
    if 'metrics' in exp and isinstance(exp['metrics'], dict):
        for k in exp['metrics']:
            field_counts[f"metrics.{k}"] = field_counts.get(f"metrics.{k}", 0) + 1
    for k in exp:
        if any(term in k.lower() for term in ['eval', 'ppl', 'downstream']):
            field_counts[k] = field_counts.get(k, 0) + 1

for f, c in sorted(field_counts.items(), key=lambda x: -x[1]):
    print(f"  {f}: {c} experiments")

